"""Author batch 1: the fifteen empty mathematics chapter/activity scopes."""
from chapter_practice_authoring import Batch

b = Batch('math')
g2, up, low = 'math-g2-upper', 'math-g7-upper', 'math-g7-lower'
N, C = b.number, b.choice
for i in range(4):
    a, d = i + 3, i + 2
    relation = '同一题型的数值变式；不算新知识点'
    N(g2, '1', 'easy', '按颜色整理', f'盒里有红积木{a}块、蓝积木{d}块、黄积木2块。按颜色分，红积木有多少块？', a, str(a), '只数指定颜色。', f'题中红积木有{a}块。', '块', relation)
    N(g2, '1', 'normal', '分类后比较', f'按形状整理卡片：圆形{a+4}张、三角形{a}张、正方形2张。圆形比三角形多几张？', 4, f'{a+4}-{a}', '比较两类的数量。', f'{a+4}−{a}=4张。', '张', relation)
    N(g2, '1', 'hard', '同一物品两种分法', f'{a+8}个按钮，按颜色分成红色{a}个和蓝色8个；按形状分成圆形{a+3}个和方形若干个。每个按钮只属于一种形状，方形有几个？', 5, f'{a+8}-({a}+3)', '换分类标准，总数不变。', f'按形状的总数仍是{a+8}，方形有{a+8}−{a+3}=5个。', '个', relation)
    dirs = ['北', '东', '南', '西']; facing = dirs[i]
    C(g2, 'activity1', 'easy', '认方向', f'你站在操场上面向{facing}，你的背后是什么方向？', dirs[(i+2)%4], [x for x in dirs if x != dirs[(i+2)%4]], '相对的方向相反。', f'{facing}与{dirs[(i+2)%4]}相对。')
    C(g2, 'activity1', 'normal', '面对方向找右边', f'校园导游面向{facing}，右手指向什么方向？', dirs[(i+1)%4], [x for x in dirs if x != dirs[(i+1)%4]], '想象自己转到这个朝向，再判断右边。', f'面向{facing}时，右边是{dirs[(i+1)%4]}。')
    C(g2, 'activity1', 'hard', '转身后辨方向', f'你原来面向{facing}，先向右转，再向右转。现在面向什么方向？每次都转到相邻方向。', dirs[(i+2)%4], [x for x in dirs if x != dirs[(i+2)%4]], '依次记录两次右转。', f'先由{facing}转向{dirs[(i+1)%4]}，再转向{dirs[(i+2)%4]}。')
    N(g2, '4', 'easy', '尺子不从零开始', f'铅笔一端对准直尺{i+1}厘米刻度，另一端对准{i+8}厘米刻度。铅笔长多少厘米？', 7, f'{i+8}-{i+1}', '终点刻度减起点刻度。', f'{i+8}−{i+1}=7厘米。', '厘米', relation)
    N(g2, '4', 'normal', '米和厘米', f'一条彩带长1米，剪去{20+i*10}厘米，还剩多少厘米？', 80-i*10, f'100-{20+i*10}', '先统一成厘米。', f'1米=100厘米，100−{20+i*10}={80-i*10}厘米。', '厘米', relation)
    N(g2, '4', 'hard', '两次截取', f'有1米长的绳子，先剪下{a*10}厘米，再剪下{d*5}厘米。还剩多少厘米？', 100-a*10-d*5, f'100-{a*10}-{d*5}', '统一单位，再减去两次剪掉的长度。', f'100−{a*10}−{d*5}={100-a*10-d*5}厘米。', '厘米', relation)
    N(g2, 'activity2', 'easy', '用自己的拃测量', f'小林量得自己一拃长{10+i}厘米。他把手连续放{d}次，首尾相接、不重叠地量桌边。桌边长多少厘米？', (10+i)*d, f'{10+i}*{d}', '一拃长度乘拃数。', f'{10+i}×{d}={(10+i)*d}厘米。', '厘米', relation)
    N(g2, 'activity2', 'normal', '整拃和剩余长度', f'小悦一拃长{10+i}厘米，书架长{d}拃还多3厘米。书架长多少厘米？', (10+i)*d+3, f'{10+i}*{d}+3', '先算整拃，再加不足一拃的长度。', f'{10+i}×{d}+3={(10+i)*d+3}厘米。', '厘米', relation)
    N(g2, 'activity2', 'hard', '身体尺要先校准', f'同一段直边，小安用{d}拃正好量完。已知小安一拃长{12+i*2}厘米；小乐的一拃比小安短2厘米。求这段直边长多少厘米。', d*(12+i*2), f'{d}*{12+i*2}', '使用实际量这段直边的人的拃长。', f'测量者是小安，应算{d}×{12+i*2}={d*(12+i*2)}厘米，不能换用小乐的拃长。', '厘米', relation)
    N(g2, '6', 'easy', '复习乘除关系', f'{d}盒彩笔，每盒{a}支，一共多少支？', a*d, f'{a}*{d}', '同样多的几组用乘法。', f'{a}×{d}={a*d}支。', '支', relation)
    N(g2, '6', 'normal', '先分再合', f'{a*d}张贴纸平均分给{d}人，小玉是其中一人，又得到3张。小玉现在有几张？', a+3, f'{a*d}/{d}+3', '先求每人分到的，再加新得到的。', f'{a*d}÷{d}+3={a+3}张。', '张', relation)
    N(g2, '6', 'hard', '不同包装凑总数', f'同样的笔，{d}袋每袋{a}支，另有2袋每袋4支。共送出5支后，还剩几支？', a*d+3, f'{d}*{a}+2*4-5', '分别算两种包装，再合起来减去送出的。', f'{d}×{a}+2×4−5={a*d+3}支。', '支', relation)
    N(up, '1', 'easy', '相反数', f'数{-(i+4)}的相反数是多少？', i+4, f'0-({-(i+4)})', '相反数与原数相加为零。', f'{-(i+4)}与{i+4}相加为0，所以相反数是{i+4}。', relation=relation)
    N(up, '1', 'normal', '数轴的距离', f'数轴上点A表示{-(i+3)}，点B表示{i+5}，A、B之间相距几个单位长度？', 2*i+8, f'{i+5}-({-(i+3)})', '两点跨过零点，可分别计算到零的距离。', f'距离为{i+3}+{i+5}={2*i+8}。', relation=relation)
    N(up, '1', 'hard', '绝对值与位置', f'数轴上一个数的绝对值为{i+5}，且它位于−2左侧。这个数是多少？', -(i+5), f'-({i+5})', '绝对值相同的非零数有两个，结合位置选一个。', f'候选为±{i+5}；只有−{i+5}在−2左侧。', relation=relation)
    N(up, '3', 'easy', '代入求值', f'当x={d}时，代数式3x+2的值是多少？', 3*d+2, f'3*{d}+2', '把x换成给定值。', f'3×{d}+2={3*d+2}。', relation=relation)
    N(up, '3', 'normal', '从数量关系到值', f'购买{a}本同价笔记本，每本x元，另付包装费5元。若x={d}，总费用是多少元？', a*d+5, f'{a}*{d}+5', '本数乘单价，再加包装费。', f'费用式为{a}x+5，代入得{a}×{d}+5={a*d+5}元。', '元', relation)
    N(up, '3', 'hard', '代数式的整体代入', f'已知2x+3={2*d+3}，求4x+11的值。', 4*d+11, f'2*{2*d+3}+5', '将4x+11表示成2x+3的倍数加常数。', f'4x+11=2(2x+3)+5=2×{2*d+3}+5={4*d+11}。', relation=relation)
    N(up, '4', 'easy', '合并同类项的系数', f'合并{a}x+{d}x后，x的系数是多少？', a+d, f'{a}+{d}', '相同字母部分不变，只加系数。', f'{a}x+{d}x=({a}+{d})x={a+d}x，系数为{a+d}。', relation=relation)
    N(up, '4', 'normal', '括号前的负号', f'化简{a}x−({d}x−5)后，代入x=2，结果是多少？', 7, f'{a}*2-({d}*2-5)', '去括号时括号内两项都变号。', f'{a}x−{d}x+5=x+5，代入x=2得7。', relation=relation)
    N(up, '4', 'hard', '合并后再代入', f'当x=−2时，求{a}(x+1)−{d}(x−2)+3x的值。', -a+4*d-6, f'{a}*(-2+1)-{d}*(-2-2)+3*(-2)', '可先展开、合并，也可分别计算各部分。', f'合并为4x+{a+2*d}；代入−2得−8+{a+2*d}={-a+4*d-6}。', relation=relation)
    N(up, '6', 'easy', '线段中点', f'线段AB长{2*a}厘米，M是其中点。AM长多少厘米？', a, f'{2*a}/2', '中点把线段分成相等两段。', f'AM=AB÷2={2*a}÷2={a}厘米。', '厘米', relation)
    N(up, '6', 'normal', '角平分线', f'∠AOB={50+i*10}°，OC是其内部的角平分线。∠AOC是多少度？', 25+i*5, f'{50+i*10}/2', '角平分线把角分成两个相等的角。', f'∠AOC={50+i*10}°÷2={25+i*5}°。', '度', relation)
    N(up, '6', 'hard', '线段上的顺序', f'A、B、C依次在同一直线上，AB={a}厘米，BC={d}厘米。M是AC中点。求BM的长度。', '1/2', f'({a}-{d})/2', '先定位中点相对于B的位置，再求距离。', f'AC={a+d}，AM={a+d}/2；AB比AM大，BM={a}−{a+d}/2=1/2厘米。', '厘米', relation)
    N(low, '7', 'easy', '对顶角', f'两条直线相交，一个角为{35+i*10}°，它的对顶角是多少度？', 35+i*10, str(35+i*10), '对顶角相等。', f'对顶角相等，所以为{35+i*10}°。', '度', relation)
    N(low, '7', 'normal', '平行线的同旁内角', f'两条平行线被第三条直线所截，一对同旁内角中的一个是{60+i*10}°，另一个是多少度？', 120-i*10, f'180-{60+i*10}', '平行线的同旁内角互补。', f'另一个角为180°−{60+i*10}°={120-i*10}°。', '度', relation)
    N(low, '7', 'hard', '角平分与邻补', f'两直线相交，∠AOB与∠BOC是邻补角。OD平分∠AOB，∠AOD={25+i*5}°。求∠BOC。', 130-i*10, f'180-2*{25+i*5}', '先还原被平分的角，再用邻补关系。', f'∠AOB=2×{25+i*5}°，∠BOC=180°−{50+i*10}°={130-i*10}°。', '度', relation)
    N(low, '8', 'easy', '算术平方根', f'{a*a}的算术平方根是多少？', a, str(a), '算术平方根取非负值。', f'{a}×{a}={a*a}且{a}≥0，因此算术平方根为{a}。', relation=relation)
    N(low, '8', 'normal', '负数的立方根', f'{-a*a*a}的立方根是多少？', -a, str(-a), '哪个数的三次方等于题中的数？', f'(−{a})³=−{a*a*a}，立方根是−{a}。', relation=relation)
    N(low, '8', 'hard', '夹逼无理数', f'满足n＜√{a*a+2}＜n+1的整数n是多少？', a, str(a), '比较相邻整数的平方。', f'{a}²={a*a}＜{a*a+2}＜{(a+1)*(a+1)}=({a+1})²，所以n={a}。', relation=relation)
    N(low, '9', 'easy', '读点的横坐标', f'点P的坐标为({-a}, {d})，它的横坐标是多少？', -a, str(-a), '有序数对的第一个数是横坐标。', f'P的横坐标为−{a}。', relation=relation)
    N(low, '9', 'normal', '平移后的纵坐标', f'点A({a}, −{d})向上平移{d+4}个单位，向左平移2个单位。新点的纵坐标是多少？', 4, f'-{d}+{d+4}', '上移增加纵坐标；左右移动不改变纵坐标。', f'新纵坐标为−{d}+{d+4}=4。', relation=relation)
    N(low, '9', 'hard', '坐标中的距离', f'A(−{a}, {d})、B({a}, {d})和C(0, {d+3})构成三角形。以AB为底，这个三角形的面积是多少平方单位？', a*3, f'({a}-(-{a}))*3/2', 'AB水平，C到AB的竖直距离是高。', f'底AB={2*a}，高=3，面积={2*a}×3÷2={3*a}。', relation=relation)
    N(low, '10', 'easy', '二元方程的一个量', f'x+y={a+d}，已知x={a}，求y。', d, f'{a+d}-{a}', '将已知x代入。', f'y={a+d}−{a}={d}。', relation=relation)
    N(low, '10', 'normal', '加减消元', f'方程组x+y={a+d}，x−y={a-d}，求x。', a, f'({a+d}+{a-d})/2', '两式相加消去y。', f'2x={a+d}+{a-d}={2*a}，x={a}。', relation=relation)
    N(low, '10', 'hard', '两种门票', f'成人票每张20元，儿童票每张10元。共买{a+d}张票，花{20*a+10*d}元。成人票有几张？', a, f'({20*a+10*d}-10*{a+d})/(20-10)', '设两类票数，分别列总张数和总价关系。', f'设成人x张，则20x+10({a+d}−x)={20*a+10*d}，解得x={a}。', '张', relation)
    N(low, '11', 'easy', '不等式的最小整数解', f'不等式x＞{a}的最小整数解是多少？', a+1, f'{a}+1', '严格大于，不能等于边界。', f'大于{a}的整数从{a+1}开始。', relation=relation)
    N(low, '11', 'normal', '负系数不等式', f'满足−2x＜{2*a}的最小整数x是多少？', 1-a, f'-{a}+1', '除以负数时不等号方向要改变。', f'两边除以−2得x＞−{a}，最小整数为{1-a}。', relation=relation)
    N(low, '11', 'hard', '不等式组计数', f'同时满足2x＞{2*d}和3x≤{3*(d+4)}的整数x有几个？', 4, f'{d+4}-{d}', '先找共同区间，再数整数。', f'公共范围是{d}＜x≤{d+4}，整数为{d+1}、{d+2}、{d+3}、{d+4}，共4个。', '个', relation)
    N(low, '12', 'easy', '频数合计', f'调查同学最喜欢的一种水果，苹果{a}人、香蕉{d}人、橘子4人，每人只选一种。共调查多少人？', a+d+4, f'{a}+{d}+4', '互不重复的各类人数相加。', f'{a}+{d}+4={a+d+4}人。', '人', relation)
    N(low, '12', 'normal', '扇形统计图', f'在扇形统计图中，某类占总体的{10+i*5}%。它所对应的圆心角是多少度？', 36+i*18, f'360*{10+i*5}/100', '整圆360°乘该类比例。', f'360°×{10+i*5}%={36+i*18}°。', '度', relation)
    N(low, '12', 'hard', '样本估计总体', f'从800名学生中随机抽取80人调查，样本中有{20+i*4}人步行到校。用样本比例估计全校步行到校的学生人数。', 200+i*40, f'800*{20+i*4}/80', '这是比例估计，不是对全体的精确清点。', f'估计人数=800×{20+i*4}/80={200+i*40}人；抽样会有误差。', '人', relation)

if __name__ == '__main__':
    b.write()
